function magicalString(n) {
  const s = [1, 2, 2];
  let read = 2;

  while (s.length < n) {
    const next = s[s.length - 1] === 1 ? 2 : 1;
    for (let k = 0; k < s[read]; k++) {
      s.push(next);
    }
    read++;
  }

  let ones = 0;
  for (let i = 0; i < n; i++) {
    if (s[i] === 1) {
      ones++;
    }
  }
  return ones;
}

