function magicalString(n) {
  // Expand the description repeatedly: the runs described by a correct prefix form a longer correct prefix.
  let t = '122';
  while (t.length < n) {
    let longer = '';
    for (let g = 0; g < t.length; g++) longer += (g % 2 === 0 ? '1' : '2').repeat(Number(t[g]));
    t = longer;
  }
  return t.slice(0, n).split('').filter(c => c === '1').length;
}

